SELECT m.entry_stage, p.status, COUNT(*) AS n, SUM(p.realized_pnl < 0) AS losses, ROUND(SUM(p.realized_pnl), 6) AS pnl_sum, ROUND(AVG(s.risk_reward_ratio), 3) AS avg_rr FROM paper_position p JOIN wallet_managed_position m ON m.entry_signal_id = p.signal_id JOIN trade_signal s ON s.id = p.signal_id WHERE p.status IN ('CLOSED','STOPPED') AND p.closed_at IS NOT NULL GROUP BY m.entry_stage, p.status ORDER BY m.entry_stage, p.status